INSERT INTO public.adoption_applications VALUES ('aa1', 'al1', 'sh1', 'p13', 'Marlow', 'https://images.unsplash.com/photo-1568572933382-74d440642117?w=800&h=600&fit=crop&crop=entropy&auto=format&q=75', 'u3', 'submitted', 5000, 2, 0, false, '', 'house', true, true, 4, 'Had a beagle for fourteen years. She died in March.', 'We saw how long Marlow has been waiting. A quiet old dog is exactly what we were hoping for — we have a single-storey house and not much traffic.', '', NULL, NULL, '2026-09-17 17:33:43.238+05', '2026-09-17 17:33:43.238+05');
INSERT INTO public.adoption_applications VALUES ('aa2', 'al2', 'sh1', 'p14', 'Pepper', 'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800&h=600&fit=crop&crop=entropy&auto=format&q=75', 'u5', 'under_review', 2500, 1, 0, true, 'One neutered male cat, six years old, very laid back.', 'apartment', false, false, 7, 'Cats my whole life.', 'My landlord allows two. Happy to do a slow introduction.', 'Landlord letter received. Arranging a meet.', NULL, NULL, '2026-09-11 17:33:43.238+05', '2026-09-18 17:33:43.238+05');
INSERT INTO public.adoption_applications VALUES ('aa3', 'al3', 'sh2', 'p15', 'Juniper', 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800&h=600&fit=crop&crop=entropy&auto=format&q=75', 'u4', 'approved', 15000, 2, 1, false, '', 'house', true, true, 2, 'We compete in agility with our older collie, who died last year. We know what this breed needs.', 'We have five acres and a very bored agility course.', 'Home check done, references excellent. Approved — settle the fee and we''ll arrange collection.', NULL, NULL, '2026-09-09 17:33:43.238+05', '2026-09-19 17:33:43.238+05');
INSERT INTO public.pets VALUES ('p1', 'u1', '1970-01-01 05:00:00+05', 'Biscuit', 'dog', 'Golden Retriever', 'male', '2021-05-12', 68, 'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{}', 'Friendly with everyone, pulls a little on the leash when he spots a squirrel.', '2 cups dry food, morning and evening. No table scraps.', 'South Austin Animal Hospital', '(512) 555-0700');
INSERT INTO public.pets VALUES ('p2', 'u1', '1970-01-01 05:00:00+05', 'Miso', 'cat', 'Domestic Shorthair', 'female', '2020-09-30', 10, 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{}', 'Shy at first, warms up with treats. Hides under the bed during storms.', '1/3 cup dry food twice daily. Fresh water fountain.', 'South Austin Animal Hospital', '(512) 555-0700');
INSERT INTO public.pets VALUES ('p3', 'u2', '1970-01-01 05:00:00+05', 'Cooper', 'dog', 'Border Collie', 'male', '2022-03-08', 42, 'https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{}', 'High energy, needs a real run daily. Knows sit, stay, and fetch.', '1.5 cups dry food twice daily.', 'Lamar Vet Clinic', '(512) 555-0711');
INSERT INTO public.pets VALUES ('p4', 'u3', '1970-01-01 05:00:00+05', 'Luna', 'cat', 'Ragdoll', 'female', '2019-11-21', 12, 'https://images.unsplash.com/photo-1495360010541-f48722b34f7d?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{Chicken,"Certain grains"}', '{"Gabapentin 25mg — 1 capsule if traveling/anxious"}', 'Very affectionate lap cat. Sensitive stomach — stick to her food exactly.', 'Grain-free salmon formula, 1/4 cup 3× daily. No chicken treats.', 'Cherry Creek Veterinary', '(303) 555-0722');
INSERT INTO public.pets VALUES ('p5', 'u3', '1970-01-01 05:00:00+05', 'Waffle', 'dog', 'Corgi', 'male', '2023-01-17', 28, 'https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{}', 'Puppy energy, still learning recall. Loves other dogs.', '1 cup puppy formula, 3× daily.', 'Cherry Creek Veterinary', '(303) 555-0722');
INSERT INTO public.pets VALUES ('p6', 'u4', '1970-01-01 05:00:00+05', 'Pepper', 'dog', 'Miniature Schnauzer', 'female', '2018-07-04', 16, 'https://images.unsplash.com/photo-1583337130417-3346a1be7dee?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{"Apoquel 5.4mg — 1 tablet with breakfast for itching"}', 'Senior dog, calm and gentle. A bit hard of hearing — approach where she can see you.', '3/4 cup senior formula twice daily. Meds with breakfast.', 'Highlands Animal Clinic', '(303) 555-0733');
INSERT INTO public.pets VALUES ('p7', 'u5', '1970-01-01 05:00:00+05', 'Ziggy', 'other', 'Holland Lop Rabbit', 'male', '2023-06-02', 4, 'https://images.unsplash.com/photo-1425082661705-1834bfd09dca?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', false, '{}', '{}', 'Litter-trained. Needs daily out-of-hutch time. Do not pick up by the ears (obviously).', 'Unlimited timothy hay, 1/4 cup pellets, fresh greens daily.', 'Exotic Pet Vet PDX', '(503) 555-0744');
INSERT INTO public.pets VALUES ('p8', 'u5', '1970-01-01 05:00:00+05', 'Olive', 'cat', 'Tuxedo', 'female', '2021-02-14', 9, 'https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{}', 'Independent, mostly wants to be left alone but likes a window seat.', 'Wet food AM, dry food available all day.', 'Exotic Pet Vet PDX', '(503) 555-0744');
INSERT INTO public.pets VALUES ('p9', 'u6', '1970-01-01 05:00:00+05', 'Rex', 'dog', 'German Shepherd', 'male', '2020-08-19', 78, 'https://images.unsplash.com/photo-1534361960057-19889db9621e?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{}', 'Well-trained and protective. Wary of strangers until introduced calmly.', '3 cups dry food twice daily. Slow-feed bowl.', 'Rose City Veterinary', '(503) 555-0755');
INSERT INTO public.pets VALUES ('p10', 'u13', '1970-01-01 05:00:00+05', 'Mochi', 'cat', 'British Shorthair', 'male', '2022-12-01', 13, 'https://images.unsplash.com/photo-1592194996308-7b43878e84a6?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{}', 'Chill and food-motivated. Will headbutt you for attention.', '1/2 cup dry food twice daily. Weight management formula.', 'South Austin Animal Hospital', '(512) 555-0700');
INSERT INTO public.pets VALUES ('p11', 'u14', '1970-01-01 05:00:00+05', 'Duke', 'dog', 'Labrador Retriever', 'male', '2021-10-10', 74, 'https://images.unsplash.com/photo-1601758228041-f3b2795255f1?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{Beef}', '{}', 'Big goofball, loves water. Will eat anything — watch him around trash.', '2.5 cups fish-based formula twice daily. No beef treats.', 'Washington Park Vet', '(303) 555-0766');
INSERT INTO public.pets VALUES ('p12', 'u2', '1970-01-01 05:00:00+05', 'Clementine', 'dog', 'Cavalier King Charles Spaniel', 'female', '2022-05-25', 15, 'https://images.unsplash.com/photo-1583795128727-6ec3642408f8?w=900&h=700&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{}', 'Sweet lapdog, great with kids. Mild separation anxiety — leave a worn t-shirt.', '1/2 cup twice daily. Prone to overeating — no free feeding.', 'Lamar Vet Clinic', '(512) 555-0711');
INSERT INTO public.pets VALUES ('p13', 'u24', '2026-05-21 17:33:43.238+05', 'Marlow', 'dog', 'Beagle mix', 'male', '2017-04-02', 28, 'https://images.unsplash.com/photo-1568572933382-74d440642117?w=800&h=600&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{"Carprofen 25mg — daily, for arthritis"}', 'Nine years old and entirely done with excitement. Sleeps through most of the day, walks about a mile, and would like the sofa. Good with everyone; slow on stairs.', '1 cup senior kibble twice daily, softened with warm water.', 'Austin Pets Alive Clinic', '(512) 555-0431');
INSERT INTO public.pets VALUES ('p14', 'u24', '2026-08-13 17:33:43.238+05', 'Pepper', 'cat', 'Domestic shorthair', 'female', '2023-08-19', 9, 'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800&h=600&fit=crop&crop=entropy&auto=format&q=75', true, '{}', '{}', 'Lived with two other cats and was the calmest of the three. Has never met a dog and we would rather she didn''t. Hides for a day in a new house, then decides you are hers.', 'Wet food morning and evening; dry food left out.', 'Austin Pets Alive Clinic', '(512) 555-0431');
INSERT INTO public.pets VALUES ('p15', 'u25', '2026-09-01 17:33:43.238+05', 'Juniper', 'dog', 'Border Collie', 'female', '2024-02-11', 34, 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800&h=600&fit=crop&crop=entropy&auto=format&q=75', true, '{Chicken}', '{}', 'Two years old and needs a job. Knows sit, down and her name, and will learn anything you can be bothered to teach her. Not a first dog, and not an apartment dog.', '2 cups grain-free twice daily — she reacts to chicken, so check the label.', 'Dripping Springs Veterinary', '(512) 555-0688');
INSERT INTO public.adoption_listings VALUES ('al1', 'sh1', 'p13', 'available', 5000, 'usd', 'Nine years old and looking for a sofa', 'Marlow came in when his owner went into care. He is arthritic, he is not interested in your other dog''s games, and he is the easiest animal in this building. He has been here four months because people scroll past grey faces. His medication costs about $18 a month and we will send you off with a month of it.', 'yes', 'yes', 'unknown', 'yes', 'low', true, 'Daily anti-inflammatory for arthritis. Needs a home without many stairs.', true, true, 'Austin', 'TX', 30.2545, -97.7688, '2026-05-21 17:33:43.238+05', '2026-05-23 17:33:43.238+05', NULL, '2026-05-21 17:33:43.238+05', '2026-05-23 17:33:43.238+05');
INSERT INTO public.adoption_listings VALUES ('al2', 'sh1', 'p14', 'available', 2500, 'usd', 'Quiet, tidy, and would like to be an only cat — or one of several', 'Pepper was surrendered with two other cats when their owner''s landlord changed the rules. Her siblings have been adopted. She is calm, she uses the tray, and she asks for very little.', 'yes', 'no', 'yes', 'yes', 'low', false, '', true, true, 'Austin', 'TX', 30.2545, -97.7688, '2026-08-13 17:33:43.238+05', '2026-08-16 17:33:43.238+05', NULL, '2026-08-13 17:33:43.238+05', '2026-08-16 17:33:43.238+05');
INSERT INTO public.adoption_listings VALUES ('al3', 'sh2', 'p15', 'pending', 15000, 'usd', 'A working dog who needs a job', 'Juniper is in foster with a family who run her twice a day and she is still ahead of them. She would be miserable in a flat and magnificent on a farm, at agility, or with anyone who wants a dog to do things with. She reacts to chicken — it took us a while to work that out, and it is in her record now so it will follow her.', 'yes', 'yes', 'no', 'yes', 'high', false, '', true, true, 'Wimberley', 'TX', 29.9974, -98.0975, '2026-09-01 17:33:43.238+05', '2026-09-03 17:33:43.238+05', NULL, '2026-09-01 17:33:43.238+05', '2026-09-03 17:33:43.238+05');
INSERT INTO public.caretaker_profiles VALUES ('c1', 'u7', 'Former vet-tech turned full-time dog walker. I treat every dog like my own and send photo updates after each visit. Ten years around big-breed dogs.', '{walking,daycare,sitting}', 8, '{dog}', true, true, true, '{"Pet First Aid & CPR","Certified Vet Assistant"}', 'verified', 4.9, 127, 50);
INSERT INTO public.caretaker_profiles VALUES ('c2', 'u8', 'Cozy home boarding with a big fenced backyard. Cats and small dogs welcome. Your pet gets the couch, the sunbeam, and a lot of belly rubs.', '{boarding,sitting,daycare}', 12, '{dog,cat}', true, false, true, '{"Pet First Aid & CPR"}', 'verified', 4.8, 89, 100);
INSERT INTO public.caretaker_profiles VALUES ('c3', 'u9', 'Energetic student who lives for trail runs and long walks. Perfect for high-energy pups who need to burn it off. New to the platform, eager to build reviews.', '{walking,daycare}', 6, '{dog}', false, false, true, '{}', 'pending', 4.5, 12, 100);
INSERT INTO public.caretaker_profiles VALUES ('c4', 'u10', 'Retired nurse offering calm, attentive care. I specialize in senior pets and those needing medication. Slow mornings, gentle walks, lots of patience.', '{sitting,boarding,walking}', 10, '{dog,cat,other}', true, false, true, '{"Pet First Aid & CPR","Senior Pet Care Certificate","Medication Administration"}', 'verified', 5, 64, 67);
INSERT INTO public.caretaker_profiles VALUES ('c5', 'u11', 'Full-time professional pet sitter and boarder. Fully booked most weeks — book early! I run a tight, safe operation with a max of three dogs at a time.', '{boarding,daycare,sitting}', 15, '{dog,cat}', true, true, true, '{"Pet First Aid & CPR","Insured & Bonded"}', 'verified', 4.7, 203, 100);
INSERT INTO public.caretaker_profiles VALUES ('c6', 'u12', 'Cat person through and through. In-home cat sitting, litter, feeding, play, and plenty of updates. Your cat stays comfortable in their own space.', '{sitting}', 9, '{cat,other}', false, true, true, '{}', 'none', 4.6, 31, 100);
INSERT INTO public.caretaker_profiles VALUES ('c7', 'u13', 'Weekend warrior caretaker — I board dogs at my place Friday through Sunday. Big yard, other friendly dogs, endless fetch. Weekdays I''m booking for my own pup!', '{boarding,daycare}', 11, '{dog}', true, true, true, '{"Pet First Aid & CPR"}', 'verified', 4.8, 47, 100);
INSERT INTO public.caretaker_profiles VALUES ('c8', 'u14', 'Dog walker and daycare host with a home office, so your dog is never alone. I keep a calm pack and match dogs by temperament and energy.', '{walking,daycare,sitting}', 10, '{dog,cat}', true, true, true, '{"Pet First Aid & CPR","Insured & Bonded"}', 'verified', 4.9, 78, 50);
INSERT INTO public.caretaker_profiles VALUES ('c9', 'u15', 'All-species sitter — dogs, cats, rabbits, birds, you name it. Experienced with exotics and special diets. In-home visits or boarding at my quiet place.', '{sitting,boarding,walking,daycare}', 13, '{dog,cat,other}', true, false, true, '{"Pet First Aid & CPR","Exotic Animal Care"}', 'verified', 4.7, 55, 100);
INSERT INTO public.caretaker_profiles VALUES ('c10', 'u16', 'Easygoing neighborhood dog walker, evenings and weekends. Reliable, punctual, and great with reactive dogs — I go slow and read body language.', '{walking}', 5, '{dog}', false, false, true, '{}', 'pending', 4.4, 18, 100);
