INSERT INTO public.bookings VALUES ('b1', 'u1', 'c1', '{p1}', 'walking', '2026-07-11 14:00:00+05', '2026-07-11 15:00:00+05', 'Biscuit gets pretty excited on walks — a squirrel or two will test the leash!', 'requested', '2026-07-08 13:15:00+05', 2800);
INSERT INTO public.bookings VALUES ('b2', 'u3', 'c4', '{p4}', 'sitting', '2026-07-14 18:00:00+05', '2026-07-14 22:00:00+05', 'Luna needs her gabapentin if she seems anxious. Grain-free food only.', 'requested', '2026-07-08 15:02:00+05', 10400);
INSERT INTO public.bookings VALUES ('b3', 'u6', 'c8', '{p9}', 'daycare', '2026-07-12 13:00:00+05', '2026-07-12 23:00:00+05', 'Rex is protective — please do a calm intro. He warms up fast once he knows you.', 'requested', '2026-07-08 00:30:00+05', 5000);
INSERT INTO public.bookings VALUES ('b4', 'u2', 'c1', '{p3}', 'daycare', '2026-07-10 13:00:00+05', '2026-07-10 22:00:00+05', 'Cooper has tons of energy — a midday run would be amazing.', 'accepted', '2026-07-06 19:20:00+05', 5500);
INSERT INTO public.bookings VALUES ('b5', 'u4', 'c4', '{p6}', 'boarding', '2026-07-18 20:00:00+05', '2026-07-21 16:00:00+05', 'Pepper is a senior — Apoquel with breakfast. She''s easy and gentle.', 'accepted', '2026-07-05 14:45:00+05', 21000);
INSERT INTO public.bookings VALUES ('b6', 'u5', 'c9', '{p7,p8}', 'sitting', '2026-07-13 15:00:00+05', '2026-07-13 19:00:00+05', 'Ziggy (rabbit) needs out-of-hutch time; Olive (cat) just needs feeding and a window.', 'accepted', '2026-07-04 21:10:00+05', 10000);
INSERT INTO public.bookings VALUES ('b7', 'u1', 'c2', '{p2}', 'boarding', '2026-07-06 17:00:00+05', '2026-07-09 17:00:00+05', 'Miso is shy — give her space the first few hours and she''ll come around.', 'in_progress', '2026-06-30 16:00:00+05', 18600);
INSERT INTO public.bookings VALUES ('b8', 'u14', 'c5', '{p11}', 'boarding', '2026-07-07 14:00:00+05', '2026-07-10 14:00:00+05', 'Duke loves water and will eat anything — watch the trash. No beef.', 'in_progress', '2026-07-01 18:25:00+05', 17400);
INSERT INTO public.bookings VALUES ('b9', 'u2', 'c8', '{p12}', 'walking', '2026-06-28 14:00:00+05', '2026-06-28 15:00:00+05', 'Clementine has mild separation anxiety — a worn t-shirt helps.', 'completed', '2026-06-25 13:00:00+05', 2600);
