INSERT INTO public.vet_profiles VALUES ('v1', 'u17', 'South Austin Animal Hospital', 'General practice with a particular interest in nutrition and weight management. I''d rather spend twenty minutes on a feeding plan than sell you a supplement.', '{general,nutrition}', 'TX-VM-44219', 'TX', 'verified', 12, '{dog,cat}', '{in_clinic,video}', false, 'Austin', 'TX', 30.259, -97.748, 4.9, 214, 75, 8500);
INSERT INTO public.vet_profiles VALUES ('v2', 'u18', 'Northside Veterinary Dermatology', 'Board-certified in dermatology. Most of my week is chronic itching, ear disease, and food trials — the cases that have already been through two rounds of steroids.', '{dermatology,general,emergency}', 'TX-VM-38104', 'TX', 'verified', 18, '{dog,cat}', '{in_clinic,video}', true, 'Austin', 'TX', 30.298, -97.721, 4.8, 167, 100, 14000);
INSERT INTO public.vet_profiles VALUES ('v3', 'u19', 'Front Range Surgical & Dental', 'Soft-tissue surgery and dentistry. Every dental here includes full-mouth radiographs — you can''t judge a tooth by its crown.', '{surgery,dentistry}', 'CO-VM-11987', 'CO', 'verified', 21, '{dog,cat}', '{in_clinic}', true, 'Denver', 'CO', 39.742, -104.988, 4.7, 98, 100, 16500);
INSERT INTO public.vet_profiles VALUES ('v4', 'u20', 'Willamette Exotics & Behaviour', 'Rabbits, birds, reptiles, and the behaviour cases nobody else has time for. Home visits across the east side — a fear-aggressive dog does better in its own kitchen.', '{exotics,behavior,general}', 'OR-VM-70551', 'OR', 'verified', 9, '{dog,cat,other}', '{video,home_visit,in_clinic}', false, 'Portland', 'OR', 45.523, -122.676, 4.9, 76, 100, 11000);
INSERT INTO public.vet_appointments VALUES ('a1', 'u3', 'v1', 'p4', 'in_clinic', 'Recurrent itching and over-grooming', '{Itching,"Hair loss",Over-grooming}', '2026-06-20 20:00:00+05', '2026-06-20 20:45:00+05', 'completed', 0, false, 'Second flare-up this year. Diet has not been changed.', '2026-06-16 15:12:00+05', 0, 8500);
INSERT INTO public.vet_appointments VALUES ('a2', 'u4', 'v2', 'p6', 'in_clinic', 'Atopic dermatitis review', '{Itching,"Red skin","Ear irritation"}', '2026-07-01 22:30:00+05', '2026-07-01 23:15:00+05', 'completed', 0, false, 'Six-month review while on Apoquel.', '2026-06-24 14:00:00+05', 0, 14000);
INSERT INTO public.vet_appointments VALUES ('a3', 'u1', 'v1', 'p1', 'in_clinic', 'Annual wellness exam and rabies booster', '{}', '2026-07-12 21:00:00+05', '2026-07-12 21:30:00+05', 'confirmed', 0, false, 'Booster is due in August — happy to do it early at the wellness visit.', '2026-07-03 00:24:00+05', 0, 8500);
INSERT INTO public.vet_appointments VALUES ('a4', 'u1', 'v1', 'p2', 'video', 'Occasional vomiting after meals', '{Vomiting,"Reduced appetite"}', '2026-07-15 19:00:00+05', '2026-07-15 19:30:00+05', 'requested', 0, false, 'Twice in the last week, both within an hour of eating. Otherwise bright.', '2026-07-08 13:40:00+05', 0, 8500);
