INSERT INTO public.vet_appointments VALUES ('a8', 'u1', 'v1', 'p1', 'in_clinic', 'Limping on the front right leg', '{Limping}', '2026-06-30 21:00:00+05', '2026-06-30 21:30:00+05', 'completed', 0, false, 'Started after a long hike at the weekend.', '2026-06-27 14:10:00+05', 0, 8500);
INSERT INTO public.vet_appointments VALUES ('a7', 'u5', 'v4', 'p7', 'home_visit', 'Reduced appetite and lethargy', '{"Reduced appetite",Lethargy}', '2026-07-08 23:00:00+05', '2026-07-08 23:45:00+05', 'in_progress', 0, false, 'Eating about half the usual amount for three days.', '2026-07-07 01:10:00+05', 0, 11000);
INSERT INTO public.medical_records VALUES ('mr1', 'p4', 'a1', 'v1', 'u17', 'visit_note', 'Suspected food-responsive dermatitis', 'Bilateral flank alopecia consistent with over-grooming. No fleas found. Starting an eight-week hydrolysed-protein elimination trial — nothing else by mouth, including treats. Recheck at six weeks.', '2026-06-20 20:45:00+05', '2026-08-01 20:00:00+05', NULL, NULL, NULL, NULL, '{vetline-hypoallergenic-cat-dry}', '2026-06-20 21:02:00+05');
INSERT INTO public.medical_records VALUES ('mr2', 'p4', 'a1', 'v1', 'u17', 'prescription', 'Hypoallergenic hydrolysed protein diet', 'Sole diet for eight weeks. No other food, treats, or flavoured medication during the trial.', '2026-06-20 20:45:00+05', NULL, 'VetLine Hypoallergenic Hydrolysed Protein (cat)', 'Feed 1/2 cup twice daily. Sole diet — no treats.', 3, '2026-12-20 05:00:00+05', '{vetline-hypoallergenic-cat-dry}', '2026-06-20 21:02:00+05');
INSERT INTO public.medical_records VALUES ('mr3', 'p4', 'a1', 'v1', 'u17', 'weight', 'Weight recorded: 12.0 lb', 'Body condition score 5/9. Ideal.', '2026-06-20 20:05:00+05', NULL, NULL, NULL, NULL, NULL, '{}', '2026-06-20 21:02:00+05');
INSERT INTO public.medical_records VALUES ('mr4', 'p6', 'a2', 'v2', 'u18', 'visit_note', 'Atopic dermatitis — six-month review', 'Well controlled on Apoquel. Skin quiet, ears clean. Continuing current dose and adding an omega-3 supplement for coat quality.', '2026-07-01 23:15:00+05', '2027-01-01 05:00:00+05', NULL, NULL, NULL, NULL, '{vitalcoat-omega-3-softgels,vetline-hydrolyzed-protein-dog-dry}', '2026-07-01 23:30:00+05');
INSERT INTO public.medical_records VALUES ('mr5', 'p6', 'a2', 'v2', 'u18', 'prescription', 'Apoquel 5.4 mg', 'Continue for atopic dermatitis. Recheck before further refills.', '2026-07-01 23:15:00+05', NULL, 'Apoquel (oclacitinib) 5.4 mg', '1 tablet with breakfast', 5, '2027-01-01 05:00:00+05', '{}', '2026-07-01 23:30:00+05');
INSERT INTO public.medical_records VALUES ('mr11', 'p6', 'a2', 'v2', 'u18', 'prescription', 'Hydrolysed protein diet', 'Twelve-week trial alongside the Apoquel, with a view to reducing the dose if the skin stays quiet.', '2026-07-01 23:15:00+05', NULL, 'VetLine Hydrolysed Protein (dog)', 'Feed to weight; sole diet for twelve weeks.', 4, '2027-01-01 05:00:00+05', '{vetline-hydrolyzed-protein-dog-dry}', '2026-07-01 23:30:00+05');
INSERT INTO public.medical_records VALUES ('mr6', 'p1', NULL, 'v1', 'u17', 'vaccination', 'Rabies (3-year)', 'Left hind limb. Batch RB-2291.', '2025-08-14 21:20:00+05', '2026-08-14 05:00:00+05', NULL, NULL, NULL, NULL, '{}', '2025-08-14 21:40:00+05');
INSERT INTO public.medical_records VALUES ('mr7', 'p1', NULL, 'v1', 'u17', 'vaccination', 'DHPP booster', 'Annual booster. No adverse reaction.', '2026-02-11 15:15:00+05', '2027-02-11 05:00:00+05', NULL, NULL, NULL, NULL, '{}', '2026-02-11 15:30:00+05');
INSERT INTO public.medical_records VALUES ('mr12', 'p1', 'a8', 'v1', 'u17', 'visit_note', 'Soft-tissue strain, front right', 'No swelling and full range of motion. Almost certainly a strain from overdoing it. Short lead walks only for ten days, then build back up. Recheck if he is still favouring it after two weeks.', '2026-06-30 21:30:00+05', NULL, NULL, NULL, NULL, NULL, '{}', '2026-06-30 21:45:00+05');
INSERT INTO public.medical_records VALUES ('mr8', 'p2', NULL, 'v1', 'u17', 'vaccination', 'FVRCP booster', 'Annual booster, well tolerated.', '2026-01-10 16:00:00+05', '2027-01-10 05:00:00+05', NULL, NULL, NULL, NULL, '{}', '2026-01-10 16:20:00+05');
INSERT INTO public.medical_records VALUES ('mr9', 'p11', 'a5', 'v3', 'u19', 'visit_note', 'Dental cleaning with full-mouth radiographs', 'Grade 2 tartar removed. Radiographs clear — no extractions needed. Start daily dental chews and recheck in twelve months.', '2026-06-11 22:00:00+05', '2027-06-11 05:00:00+05', NULL, NULL, NULL, NULL, '{freshgrin-dental-chews-dog}', '2026-06-11 22:25:00+05');
INSERT INTO public.medical_records VALUES ('mr10', 'p11', NULL, NULL, 'u14', 'allergy', 'Beef intolerance', 'Owner-reported: loose stools within a day of anything containing beef. Avoiding it entirely.', '2025-10-02 05:00:00+05', NULL, NULL, NULL, NULL, NULL, '{}', '2025-10-02 14:00:00+05');
