INSERT INTO public.reviews VALUES ('r1', 'b9', 'booking', 'u2', 'u14', 5, 'Ben was fantastic with Clementine. Sent a photo mid-walk and she came home happy and tired. Booking again.', '2026-06-28 17:00:00+05');
INSERT INTO public.reviews VALUES ('r2', 'b9', 'booking', 'u14', 'u2', 5, 'Clementine is a sweetheart and Daniel gave super clear instructions. Easy booking!', '2026-06-28 18:30:00+05');
INSERT INTO public.reviews VALUES ('r3', 'b10', 'booking', 'u3', 'u10', 5, 'Elena is incredibly patient with our puppy Waffle. She worked on his recall and sent updates all day.', '2026-06-20 23:00:00+05');
INSERT INTO public.reviews VALUES ('r4', 'b11', 'booking', 'u6', 'u15', 4, 'Great with Rex, who can be wary of new people. Handled him calmly. Would''ve liked one more photo update.', '2026-06-16 00:00:00+05');
INSERT INTO public.reviews VALUES ('r5', 'b12', 'booking', 'u4', 'u11', 5, 'Marcus handled Pepper''s medication schedule perfectly and she came back relaxed. Total pro operation.', '2026-06-02 17:00:00+05');
INSERT INTO public.reviews VALUES ('r6', 'b12', 'booking', 'u11', 'u4', 5, 'Pepper is the gentlest senior pup. Tom packed everything clearly labeled. 10/10 owner.', '2026-06-02 19:00:00+05');
INSERT INTO public.reviews VALUES ('vr1', 'a1', 'vet_appointment', 'u3', 'u17', 5, 'She spent twenty minutes explaining why the food trial has to be strict, instead of just handing me a bag. Luna has stopped over-grooming for the first time in a year.', '2026-06-22 14:15:00+05');
INSERT INTO public.reviews VALUES ('vr2', 'a2', 'vet_appointment', 'u4', 'u18', 5, 'Third vet we have seen for Pepper''s itching and the first to actually get it under control. Worth the drive across town.', '2026-07-03 22:40:00+05');
INSERT INTO public.reviews VALUES ('vr3', 'a5', 'vet_appointment', 'u14', 'u19', 4, 'Thorough work and the radiographs were reassuring. Only note is that the wait to get in was a few weeks longer than I expected.', '2026-06-14 16:20:00+05');
INSERT INTO public.shelter_profiles VALUES ('sh1', 'u24', 'Austin Pets Alive', 'A no-kill shelter in south Austin. We take the animals other shelters can''t — seniors, medical cases, and the ones who need a bit longer to trust somebody.', 'rescue', '74-2963682', 'TX', 'verified', '{dog,cat,other}', 'https://austinpetsalive.example.com', '(512) 555-0431', 'hello@austinpetsalive.example.com', '1156 W Cesar Chavez St', 'Austin', 'TX', 30.2545, -97.7688, 'We ask for a completed application, a phone conversation, and a meet-and-greet with everyone in the household — including any dogs already at home. Most adoptions complete within a week. The fee covers vaccination, microchipping and neutering, and we will tell you before you apply if an animal has ongoing medical costs.', 50, '2025-03-14 14:00:00+05');
INSERT INTO public.shelter_profiles VALUES ('sh2', 'u25', 'Hill Country Rescue', 'A small foster-based rescue west of Austin. Every animal here lives in somebody''s house, so we can tell you honestly how they are with stairs, cats, thunderstorms and strangers.', 'foster_network', '82-1104558', 'TX', 'verified', '{dog,cat}', 'https://hillcountryrescue.example.com', '(512) 555-0688', 'adopt@hillcountryrescue.example.com', '410 Mercer St', 'Dripping Springs', 'TX', 30.1902, -98.0867, 'Because our animals live in foster homes, you meet them where they are, and their foster carer will tell you the truth about them. We do not adopt out to homes with children under five without a conversation first.', 100, '2025-06-02 14:00:00+05');
